{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "notebook programación contenedores",
        "category": "notebooks",
        "max_price": 2000000,
        "attributes": {"ram_gb": {"min": 16}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "compare_products",
      "args": {
