      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "Para programar y correr contenedores todo el día con al menos 16 GB de RAM y presupuesto de hasta $2.000.000, encontré estas opciones:\n\n1. {nombre0} — ${precio0} <<rec:{id0}>>\n2. {nombre1} — ${precio1} <<rec:{id1}>>\n3. {nombre2} — ${precio2} <<rec:{id2}>>\n\nComparación entre las tres: el más barato es {mas_barato} y el mejor evaluado es {mejor_evaluado}. <<cmp:{id0},{id1}>> <<cmp:{id1},{id2}>> <<cmp:{id0},{id2}>>\n\nReseñas del mejor evaluado: {resenas}",
      "vars": {
        "nombre0": "$s1.0.name",
        "precio0": "$s1.0.price_clp",
        "id0": "$s1.0.id",
        "nombre1": "$s1.1.name",
        "precio1": "$s1.1.price_clp",
        "id1": "$s1.1.id",
        "nombre2": "$s1.2.name",
        "precio2": "$s1.2.price_clp",
        "id2": "$s1.2.id",
        "mas_barato": "$s2.mas_barato",
        "mejor_evaluado": "$s2.mejor_evaluado",
        "resenas": "$s3"
      }
    }
  ]
}
